import 'dart:convert';

import 'package:flutter/foundation.dart';

/// Groups that say something to whoever uses the app (SPEC-038 R6).
const _userGroups = {'Funcionalidades', 'Correções'};

/// Every group git-cliff writes (cliff.toml). A text with none of them was
/// not generated by it and is shown whole (D3).
const _knownGroups = {
  ..._userGroups,
  'Desempenho',
  'Refatoração',
  'Documentação',
  'Testes',
  'Build e CI',
  'Manutenção',
  'Reversões',
};

final _versionHeading = RegExp(
  r'^##\s+\[?v?(\d+\.\d+(?:\.\d+)?[^\]\s]*)\]?'
  r'(?:\s+-\s+(\d{4}-\d{2}-\d{2}))?\s*$',
);
final _groupHeading = RegExp(r'^###\s+(.+?)\s*$');
final _item = RegExp(r'^\s{0,3}[-*]\s+(.*)$');
final _commitHash = RegExp(r'\s*\([0-9a-f]{7,40}\)\s*$');
final _commitScope = RegExp(r'^\*\*[^*]+:\*\*\s*');

/// A group of [ChangelogSection], with its lines already cleaned.
@immutable
class ChangelogGroup {
  const ChangelogGroup(this.title, this.items);

  final String title;
  final List<String> items;
}

/// What [latestChanges] picked out of a changelog or of release notes.
@immutable
class ChangelogSection {
  const ChangelogSection({
    this.version,
    this.date,
    this.groups = const [],
    this.rawText,
  });

  /// Null when the text has no version heading.
  final String? version;
  final DateTime? date;

  /// Only the groups of R6.
  final List<ChangelogGroup> groups;

  /// The text as it came, when it doesn't follow git-cliff's format (D3).
  final String? rawText;

  bool get isEmpty => groups.isEmpty && rawText == null;

  /// What the screen renders.
  String get markdown =>
      rawText ??
      [
        for (final g in groups)
          ['### ${g.title}', '', for (final i in g.items) '- $i'].join('\n'),
      ].join('\n\n');
}

/// The news of one version, out of `CHANGELOG.md` or of release notes: the
/// section of [version] or, without it, the first version section. A text
/// without version headings counts as a single section.
ChangelogSection latestChanges(String markdown, {String? version}) {
  final lines = const LineSplitter().convert(markdown);
  final wanted = version?.replaceFirst(RegExp('^v'), '');
  RegExpMatch? heading;
  var start = -1;
  for (var i = 0; i < lines.length; i++) {
    final m = _versionHeading.firstMatch(lines[i]);
    if (m == null) continue;
    final exact = m.group(1) == wanted;
    if (heading == null || exact) {
      heading = m;
      start = i;
    }
    if (exact) break;
  }
  if (heading == null) return _parse(lines);
  final rest = lines.skip(start + 1);
  return _parse(
    rest.takeWhile((l) => !l.startsWith('## ')).toList(),
    version: heading.group(1),
    date: DateTime.tryParse(heading.group(2) ?? ''),
  );
}

ChangelogSection _parse(
  List<String> lines, {
  String? version,
  DateTime? date,
}) {
  final groups = <String, List<String>>{};
  List<String>? current;
  for (final line in lines) {
    final title = _groupHeading.firstMatch(line)?.group(1);
    if (title != null) {
      current = _knownGroups.contains(title)
          ? groups.putIfAbsent(title, () => [])
          : null;
      continue;
    }
    // Anything else is left out: the release workflow appends a link after
    // the last group.
    final item = _item.firstMatch(line)?.group(1);
    if (item != null) current?.add(_clean(item));
  }
  final text = lines.join('\n').trim();
  return ChangelogSection(
    version: version,
    date: date,
    groups: [
      for (final e in groups.entries)
        if (_userGroups.contains(e.key) && e.value.isNotEmpty)
          ChangelogGroup(e.key, e.value),
    ],
    rawText: groups.isEmpty && text.isNotEmpty ? text : null,
  );
}

String _clean(String item) =>
    item.replaceFirst(_commitHash, '').replaceFirst(_commitScope, '').trim();
